/**
 * Skill scripts run in their own Code Interpreter, with no public network.
 *
 * Model-written code keeps the existing PUBLIC interpreter; a skill's
 * `scripts/*.py` (which an author other than the invoking user may have
 * written) runs in a second, SANDBOX one. Its id is generated by the service,
 * so it reaches the Runtime through an SSM parameter named from the project
 * prefix, never through the Runtime's environment (the 2,560-byte V2 budget).
 *
 * What this pins:
 *   - the new interpreter, its network mode, role and name;
 *   - the existing interpreter, unchanged (logical id, name, properties), since
 *     `executionRoleArn` and the name are create-only and a change would
 *     replace it;
 *   - the Runtime role's grants on exactly the new interpreter and parameter;
 *   - the Runtime's environment variable names, default and worst case.
 */
import * as cdk from 'aws-cdk-lib';
import { Template } from 'aws-cdk-lib/assertions';
import { PlatformStack } from '../lib/platform-stack';
import { SKILL_SCRIPT_INTERPRETER_SSM_SUFFIX } from '../lib/constructs/agentcore/code-interpreter-construct';
import { createMockConfig, mockSsmContext, MOCK_ACCOUNT, MOCK_PREFIX, MOCK_REGION } from './helpers/mock-config';
import { runtimeEnvironment, synthWorstCasePlatformStack } from './helpers/runtime-worst-case';

interface Statement {
  Sid?: string;
  Effect?: string;
  Action?: string | string[];
  Resource?: unknown;
}

const EXISTING_LOGICAL_ID = 'AgentCoreCodeInterpreterCodeInterpreterCustomB4DBAD3D';
const EXECUTION_ROLE_LOGICAL_ID = 'AgentCoreCodeInterpreterCodeInterpreterExecutionRole5A00171B';
const SKILL_LOGICAL_ID_PREFIX = 'AgentCoreCodeInterpreterSkillScriptInterpreterCustom';
const PARAMETER_LOGICAL_ID_PREFIX = 'AgentCoreCodeInterpreterSkillScriptInterpreterIdParameter';

const SESSION_ACTIONS = [
  'bedrock-agentcore:StartCodeInterpreterSession',
  'bedrock-agentcore:InvokeCodeInterpreter',
  'bedrock-agentcore:StopCodeInterpreterSession',
  'bedrock-agentcore:GetCodeInterpreter',
  'bedrock-agentcore:GetCodeInterpreterSession',
  'bedrock-agentcore:ListCodeInterpreterSessions',
];

function synthWired(prefix?: string): Template {
  const config = createMockConfig(prefix ? { projectPrefix: prefix } : {});
  const app = new cdk.App();
  mockSsmContext(app, config);
  const stack = new PlatformStack(app, 'TestPlatformStack', {
    config,
    env: { account: MOCK_ACCOUNT, region: MOCK_REGION },
  });
  stack.wireCompute();
  return Template.fromStack(stack);
}

function oneResource(template: Template, type: string, idPrefix: string): [string, any] {
  const found = Object.entries(template.findResources(type)).filter(([id]) => id.startsWith(idPrefix));
  expect(found).toHaveLength(1);
  return found[0];
}

function runtimeStatements(template: Template): Statement[] {
  // The role's own policy and CDK's overflow managed policies both count.
  const policies = [
    ...Object.values(template.findResources('AWS::IAM::Policy')),
    ...Object.values(template.findResources('AWS::IAM::ManagedPolicy')),
  ].filter((p: any) =>
    JSON.stringify(p.Properties.Roles ?? []).includes('AgentCoreRuntimeExecutionRole'),
  );
  expect(policies.length).toBeGreaterThan(0);
  return policies.flatMap((p: any) => p.Properties.PolicyDocument.Statement as Statement[]);
}

function actions(st: Statement): string[] {
  return Array.isArray(st.Action) ? st.Action : [st.Action ?? ''];
}

describe('Skill-script Code Interpreter', () => {
  let template: Template;

  beforeAll(() => {
    template = synthWired();
  });

  it('is a second interpreter with no public network, on the logs-only role', () => {
    const [, ci] = oneResource(template, 'AWS::BedrockAgentCore::CodeInterpreterCustom', SKILL_LOGICAL_ID_PREFIX);
    expect(ci.Properties.NetworkConfiguration).toEqual({ NetworkMode: 'SANDBOX' });
    expect(ci.Properties.Name).toBe('test_project_skill_script_interpreter');
    expect(ci.Properties.ExecutionRoleArn).toEqual({ 'Fn::GetAtt': [EXECUTION_ROLE_LOGICAL_ID, 'Arn'] });
    expect(Object.keys(template.findResources('AWS::BedrockAgentCore::CodeInterpreterCustom'))).toHaveLength(2);
  });

  it('keeps the existing interpreter exactly as it was', () => {
    const existing = template.findResources('AWS::BedrockAgentCore::CodeInterpreterCustom')[EXISTING_LOGICAL_ID];
    expect(existing).toBeDefined();
    expect(existing.Properties).toEqual({
      Name: 'test_project_code_interpreter',
      Description: 'Custom Code Interpreter for Python code execution with advanced configuration',
      NetworkConfiguration: { NetworkMode: 'PUBLIC' },
      ExecutionRoleArn: { 'Fn::GetAtt': [EXECUTION_ROLE_LOGICAL_ID, 'Arn'] },
      Tags: existing.Properties.Tags,
    });
  });

  it('fits AgentCore name rules at the longest allowed prefix', () => {
    const longest = 'a2345678901234567890b'; // validateConfig allows 21 characters
    const [, ci] = oneResource(
      synthWired(longest),
      'AWS::BedrockAgentCore::CodeInterpreterCustom',
      SKILL_LOGICAL_ID_PREFIX,
    );
    expect(ci.Properties.Name).toMatch(/^[a-zA-Z][a-zA-Z0-9_]{0,47}$/);
  });

  it('publishes its id to a parameter named from the project prefix', () => {
    expect(SKILL_SCRIPT_INTERPRETER_SSM_SUFFIX).toBe('agentcore/skill-script-interpreter-id');
    const [, param] = oneResource(template, 'AWS::SSM::Parameter', PARAMETER_LOGICAL_ID_PREFIX);
    expect(param.Properties.Name).toBe(`/${MOCK_PREFIX}/agentcore/skill-script-interpreter-id`);
    expect(param.Properties.Type).toBe('String');
    const [skillId] = oneResource(template, 'AWS::BedrockAgentCore::CodeInterpreterCustom', SKILL_LOGICAL_ID_PREFIX);
    expect(param.Properties.Value).toEqual({ 'Fn::GetAtt': [skillId, 'CodeInterpreterId'] });
  });

  it('gives the Runtime session access to the new interpreter only', () => {
    const [skillId] = oneResource(template, 'AWS::BedrockAgentCore::CodeInterpreterCustom', SKILL_LOGICAL_ID_PREFIX);
    const statements = runtimeStatements(template);
    const st = statements.find((s) => s.Sid === 'SkillScriptInterpreterAccess');
    expect(st).toBeDefined();
    expect(st!.Effect).toBe('Allow');
    expect(actions(st!)).toEqual(SESSION_ACTIONS);
    expect(st!.Resource).toEqual({ 'Fn::GetAtt': [skillId, 'CodeInterpreterArn'] });

    // The existing grant still names the existing interpreter alone.
    const existing = statements.find((s) => s.Sid === 'CodeInterpreterAccess');
    expect(actions(existing!)).toEqual(SESSION_ACTIONS);
    expect(existing!.Resource).toEqual({ 'Fn::GetAtt': [EXISTING_LOGICAL_ID, 'CodeInterpreterArn'] });
  });

  it('gives the Runtime ssm:GetParameter on exactly the new parameter', () => {
    const [paramId] = oneResource(template, 'AWS::SSM::Parameter', PARAMETER_LOGICAL_ID_PREFIX);
    const st = runtimeStatements(template).find((s) => s.Sid === 'SkillScriptInterpreterIdRead');
    expect(st).toBeDefined();
    expect(st!.Effect).toBe('Allow');
    expect(actions(st!)).toEqual(['ssm:GetParameter']);
    const resource = JSON.stringify(st!.Resource);
    expect(resource).toContain(paramId);
    expect(resource).not.toContain('*');
  });
});

describe('Runtime environment with the skill-script interpreter', () => {
  // The exact variable names before this change. The interpreter's id must not
  // become one: it is read from SSM. A new variable is a deliberate edit here.
  const DEFAULT_NAMES = [
    'AGENTCORE_CODE_INTERPRETER_ID',
    'AGENTCORE_GATEWAY_INBOUND_AUTH',
    'AGENTCORE_LOCAL_OAUTH_CALLBACK_URL',
    'AGENTCORE_MCP_APPS_SANDBOX_ORIGIN',
    'AGENTCORE_MEMORY_ID',
    'AGENTS_API_ENABLED',
    'AUTH_PROVIDER_SECRETS_ARN',
    'AWS_ACCOUNT_ID',
    'AWS_DEFAULT_REGION',
    'BROWSER_ID',
    'BROWSER_POLICY_S3',
    'CONVERSATION_INDEX_ENABLED',
    'CORS_ORIGINS',
    'FOLDER_ATTACHMENTS_ENABLED',
    'FRONTEND_URL',
    'LOG_LEVEL',
    'MEMORY_LINT',
    'MEMORY_SPACES_ENABLED',
    'PLATFORM_SELF_SERVICE_ENABLED',
    'PROJECTS_ENABLED',
    'PROJECT_PREFIX',
    'SESSION_FORK_ENABLED',
    'SESSION_REWIND_ENABLED',
    'SKILLS_ENABLED',
    'SKILL_AUTHORING_ENABLED',
    'WORD_TRACKED_CHANGES_ENABLED',
  ];

  it('has the same variable names as before on the default config', () => {
    expect(Object.keys(runtimeEnvironment(synthWired())).sort()).toEqual(DEFAULT_NAMES);
  });

  it('carries no skill-script interpreter variable in the worst case either', () => {
    const names = Object.keys(runtimeEnvironment(synthWorstCasePlatformStack().template));
    expect(names.filter((n) => /SKILL_SCRIPT/.test(n))).toEqual([]);
    // PROJECT_PREFIX is what the parameter name is derived from.
    expect(names).toContain('PROJECT_PREFIX');
  });
});
